#!/usr/bin/env bash
# Writes THIRD_PARTY_NOTICES.md: licenses of the Go modules linked into the
# binaries. The web UI's bundled dependencies are listed in web/dist/licenses.md
# (generated by Vite) and served by the binary at /licenses.md.
#
#   scripts/notices.sh            regenerate THIRD_PARTY_NOTICES.md
#   scripts/notices.sh --check    fail if it is out of date
set -euo pipefail
cd "$(dirname "$0")/.."
out=THIRD_PARTY_NOTICES.md
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT

main=$(go list -m)
mods=$(go list -deps -f '{{with .Module}}{{.Path}}{{end}}' ./cmd/... | sort -u | grep -vx "$main" || true)
{
  echo "# Third-party notices"
  echo
  echo "The binaries include the following Go modules. The web UI embedded in the"
  echo "core binary bundles further dependencies; their licenses are in"
  echo "\`licenses.md\` (served at \`/licenses.md\`, generated by \`pnpm -C web build\`)."
  echo "code-server and VS Code extensions are downloaded at runtime, not bundled."
  for m in $mods; do
    dir=$(go list -m -f '{{.Dir}}' "$m")
    ver=$(go list -m -f '{{.Version}}' "$m")
    lic=$(ls "$dir" | grep -iE '^(licen[cs]e|copying)(\.(md|txt))?$' | head -1 || true)
    echo
    echo "## $m $ver"
    echo
    if [[ -n "$lic" ]]; then
      echo '```text'
      cat "$dir/$lic"
      echo '```'
    else
      echo "No license file found in the module."
    fi
  done
} > "$tmp"

if [[ "${1:-}" == "--check" ]]; then
  if ! cmp -s "$tmp" "$out"; then
    echo "$out is out of date; run scripts/notices.sh"
    exit 1
  fi
  exit 0
fi
cp "$tmp" "$out"
echo "wrote $out ($(echo "$mods" | grep -c . || true) modules)"
